/* Reciprocal iscale = 2^32/denom for denom >= 350, ~8 cycles:
 *   e      = (k << 3) + exp_lut[b]   (k = top-byte position,
 *                                     b = top nonzero byte)
 *   idx    = 9 mantissa bits after the leading 1
 *   iscale = (e <= 16) ? recip[idx] << (16-e) : recip[idx] >> (e-16)
 * exp_lut[b] = floor(log2(b)) (b >= 1 always — denom >= 350). Domain
 * extends cleanly to the full u32 (e up to 31).
 */

#define SATURN_DIVTAB_DENOM_MIN 350u

static inline unsigned Saturn_Divtab_Iscale(unsigned denom)
{
    unsigned b, k, e, idx, v;

    if ((denom >> 24) != 0) { b = denom >> 24; k = 3; }
    else if ((denom >> 16) != 0) { b = denom >> 16; k = 2; }
    else if ((denom >>  8) != 0) { b = denom >>  8; k = 1; }
    else                         { b = denom;       k = 0; }
    e = (k << 3) + saturn_exp_lut[b];

    /* mantissa: 9 bits after the leading 1 */
    if (e >= 9)
        idx = (denom >> (e - 9)) & 0x1FFu;
    else
        idx = (denom << (9 - e)) & 0x1FFu;
    v = saturn_divtab_recip[idx];
    return (e <= 16) ? (v << (16 - e)) : (v >> (e - 16));
}

